{"path": "robot_name.py", "content": "import random
import string


class Robot:
    """A robot with a random, unique name like 'RX837'."""

    _used_names = set()
    _MAX_NAMES = 26 * 26 * 1000

    def __init__(self):
        self._name = None
        self.reset()

    @property
    def name(self):
        if self._name is None:
            self._name = self._generate_name()
        return self._name

    @classmethod
    def _generate_name(cls):
        if len(cls._used_names) >= cls._MAX_NAMES:
            raise RuntimeError("No unique robot names left")
        while True:
            name = "".join(random.choice(string.ascii_uppercase) for _ in range(2))
            name += "".join(random.choice(string.digits) for _ in range(3))
            if name not in cls._used_names:
                cls._used_names.add(name)
                return name

    def reset(self):
        """Wipe the name; a new unique one is assigned immediately.

        The old name is released only after the new one is chosen, so the
        new name is guaranteed to differ from the previous one.
        """
        old_name = self._name
        self._name = self._generate_name()
        if old_name is not None:
            self._used_names.discard(old_name)
